const crmData = $('CRM Decision Agent').first().json.output ?? '';

const existingContacts = $input.all().map(item => item.json);

const customer = {};

for (const line of crmData.split('\n')) {
  const separator = line.indexOf(':');

  if (separator === -1) continue;

  const key = line.slice(0, separator).trim();
  const value = line.slice(separator + 1).trim();

  if (key === 'First Name') customer.first_name = value;
  if (key === 'Last Name') customer.last_name = value;
  if (key === 'Email') customer.email = value;
  if (key === 'Mobile') customer.mobile = value;
  if (key === 'Landline') customer.landline = value;
  if (key === 'Country') customer.country = value;
  if (key === 'State') customer.state = value;
}

return [
  {
    json: {
      new_customer: customer,
      existing_contacts: existingContacts
    }
  }
];
